package earth.terrarium.pastel.data.lang.guidebook.equipment;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class GemstoneArmorEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.gemstone_armor.name", "Gemstone Armor");
		provider.add("book.pastel.guidebook.gemstone_armor.page0.text", "I've had more than enough time to develop my own individual fighting style.\\\nTo best support it, I've designed a range of matching gear.\\\n\\\nDisadvantage: The ingredients used to make them are very brittle. Therefore, the durability of this equipment is relatively low.");
		provider.add("book.pastel.guidebook.gemstone_armor.checklist.helmet", "Helmet: when nothingness meets hell");
		provider.add("book.pastel.guidebook.gemstone_armor.checklist.chestplate", "Chestplate: the Golden Ratio");
		provider.add("book.pastel.guidebook.gemstone_armor.checklist.leggings", "Leggings: mourning of the Nether");
		provider.add("book.pastel.guidebook.gemstone_armor.checklist.boots", "Boots: the source of nightmares");
		provider.add("book.pastel.guidebook.gemstone_armor.page1.text", "\\\nThey can be repaired in [Anvils](item://minecraft:anvil) by using [Gemstone Shards](entry://general/shards).\\\n\\\nTo take advantage of their unique abilities I will need some special materials:");
		provider.add("book.pastel.guidebook.gemstone_armor.page2.text", "Gives attackers Weakness and Slowness when they hit me, allowing me to slip through their hands like a shadow.");
		provider.add("book.pastel.guidebook.gemstone_armor.page3.text", "Gives me Absorption and Resistance when hit, making me a massive wall for a short duration.");
		provider.add("book.pastel.guidebook.gemstone_armor.page4.text", "Gives me a short burst of Regeneration when hit, so I can get right back up and fight back.");
		provider.add("book.pastel.guidebook.gemstone_armor.page5.text", "Gives me a short burst of Speed and Invisibility when hit, allowing me to retreat. Perfect for ranged combat.");
	}
}
